const fu = $('Buscar follow-ups vencidos').item.json;
const msgs = ($json.payload || []).filter(m => m.message_type === 0 || m.message_type === 1);

// TRAVA 1: o lead respondeu depois que este follow-up foi agendado? Cancela — a conversa está viva.
const agendadoEm = Math.floor(new Date(fu.criado_em).getTime() / 1000);
const ultimaDoLead = [...msgs].reverse().find(m => m.message_type === 0);
if (ultimaDoLead && ultimaDoLead.created_at > agendadoEm) {
  return { json: { ...fu, acao: 'cancelar', motivo: 'lead-respondeu' } };
}

// TRAVA 2: já mandamos 3+ mensagens seguidas sem UMA resposta? Para de bater.
let seguidasSemResposta = 0;
for (let i = msgs.length - 1; i >= 0; i--) {
  if (msgs[i].message_type === 1) seguidasSemResposta++;
  else break;
}
if (seguidasSemResposta >= 3) {
  return { json: { ...fu, acao: 'cancelar', motivo: 'sem-resposta-3x' } };
}

return { json: { ...fu, acao: 'enviar' } };

const fu = $('Travas anti-chatice').item.json;

// A RÉGUA DE 90 DIAS — espera contada a partir do envio ANTERIOR.
// ⚠️ ESCREVA AS SUAS MENSAGENS. Do momento em que a janela de 24h fechar em diante,
// mensagem livre não entrega: os passos longos precisam virar TEMPLATE aprovado na Meta.
const REGUA = [
  { passo: 1,  espera_min: 5,      mensagem: '[SUA MENSAGEM - toque rápido, ex: ficou alguma dúvida?]' },
  { passo: 2,  espera_min: 30,     mensagem: '[SUA MENSAGEM - retomar o ponto onde a conversa parou]' },
  { passo: 3,  espera_min: 180,    mensagem: '[SUA MENSAGEM - agregar valor: prova, caso, benefício]' },
  { passo: 4,  espera_min: 1440,   mensagem: '[TEMPLATE - 1 dia depois]' },
  { passo: 5,  espera_min: 5760,   mensagem: '[TEMPLATE - 4 dias depois]' },
  { passo: 6,  espera_min: 10080,  mensagem: '[TEMPLATE - 7 dias depois]' },
  { passo: 7,  espera_min: 21600,  mensagem: '[TEMPLATE - 15 dias depois]' },
  { passo: 8,  espera_min: 43200,  mensagem: '[TEMPLATE - 30 dias depois]' },
  { passo: 9,  espera_min: 43200,  mensagem: '[TEMPLATE - 60 dias depois]' },
  { passo: 10, espera_min: 43200,  mensagem: '[TEMPLATE - 90 dias depois]' }
];

const prox = REGUA.find(r => r.passo === (Number(fu.passo) + 1));
if (!prox) {
  return { json: { tem_proximo: false } };
}

return { json: {
  tem_proximo: true,
  conversation_id: fu.conversation_id,
  nome_lead: fu.nome_lead,
  passo: prox.passo,
  mensagem: prox.mensagem,
  enviar_em: new Date(Date.now() + prox.espera_min * 60000).toISOString(),
  status: 'pendente'
} };
